  {
    id: 'shipping',
    label: 'Shipping',
    content: (
      <>
        <p>Free shipping on orders over $75 CAD, arriving in 2 to 4 business days.</p>
        <p>Free returns within 30 days, worn on the trail or not.</p>
      </>
    ),
