          max={MAX}
          step={1}
          value={value}
          onChange={(event) => {
            const parsed = Number(event.target.value)
            onChange(Number.isFinite(parsed) ? Math.min(MAX, Math.max(MIN, Math.round(parsed))) : MIN)
          }}
        />
        <button type="button" onClick={() => changeBy(1)} aria-controls="quantity">
          Increase quantity
        </button>
